/* Run after OperationsBulletin.sql. Existing data remains in Underwriting-Servicing (19). */
SET XACT_ABORT ON;
GO
IF NOT EXISTS(SELECT 1 FROM dbo.SubDomain WHERE SubDomainID=19)
 THROW 51000,'Underwriting-Servicing subdomain (19) was not found.',1;
IF NOT EXISTS(SELECT 1 FROM dbo.SubDomain WHERE LTRIM(RTRIM(SubdomainName))='Credit')
 THROW 51000,'Credit subdomain was not found.',1;
GO
IF COL_LENGTH('dbo.BulletinFolderMaster','SubDomainID') IS NULL ALTER TABLE dbo.BulletinFolderMaster ADD SubDomainID int NULL;
IF COL_LENGTH('dbo.BulletinMaster','SubDomainID') IS NULL ALTER TABLE dbo.BulletinMaster ADD SubDomainID int NULL;
GO
UPDATE dbo.BulletinFolderMaster SET SubDomainID=19 WHERE SubDomainID IS NULL;
UPDATE dbo.BulletinMaster SET SubDomainID=19 WHERE SubDomainID IS NULL;
ALTER TABLE dbo.BulletinFolderMaster ALTER COLUMN SubDomainID int NOT NULL;
ALTER TABLE dbo.BulletinMaster ALTER COLUMN SubDomainID int NOT NULL;
IF NOT EXISTS(SELECT 1 FROM sys.default_constraints WHERE parent_object_id=OBJECT_ID('dbo.BulletinFolderMaster') AND name='DF_BFM_SubDomain') ALTER TABLE dbo.BulletinFolderMaster ADD CONSTRAINT DF_BFM_SubDomain DEFAULT(19) FOR SubDomainID;
IF NOT EXISTS(SELECT 1 FROM sys.default_constraints WHERE parent_object_id=OBJECT_ID('dbo.BulletinMaster') AND name='DF_BM_SubDomain') ALTER TABLE dbo.BulletinMaster ADD CONSTRAINT DF_BM_SubDomain DEFAULT(19) FOR SubDomainID;
IF NOT EXISTS(SELECT 1 FROM sys.indexes WHERE object_id=OBJECT_ID('dbo.BulletinFolderMaster') AND name='IX_BFM_SubDomain') CREATE INDEX IX_BFM_SubDomain ON dbo.BulletinFolderMaster(SubDomainID,ParentFolderID,IsDeleted);
IF NOT EXISTS(SELECT 1 FROM sys.indexes WHERE object_id=OBJECT_ID('dbo.BulletinMaster') AND name='IX_BM_SubDomain') CREATE INDEX IX_BM_SubDomain ON dbo.BulletinMaster(SubDomainID,PublishStatus,IsDeleted);
GO

IF OBJECT_ID('dbo.ufn_BulletinEmployeeSubDomain') IS NULL EXEC('CREATE FUNCTION dbo.ufn_BulletinEmployeeSubDomain(@EmployeeID int) RETURNS int AS BEGIN RETURN NULL END');
GO
ALTER FUNCTION dbo.ufn_BulletinEmployeeSubDomain(@EmployeeID int)
RETURNS int AS
BEGIN
 DECLARE @SubDomainID int,@EmployeeSubDomain nvarchar(100);
 SELECT @EmployeeSubDomain=UPPER(LTRIM(RTRIM(CONVERT(nvarchar(100),e.SubDomain))))FROM dbo.EmployeeInfo e WHERE e.EmployeeID=@EmployeeID AND ISNULL(e.IsDelete,0)=0;
 SELECT TOP(1)@SubDomainID=s.SubDomainID FROM dbo.SubDomain s WHERE UPPER(LTRIM(RTRIM(s.SubdomainName)))=@EmployeeSubDomain OR(@EmployeeSubDomain='SERVICING'AND s.SubDomainID=19)ORDER BY CASE WHEN UPPER(LTRIM(RTRIM(s.SubdomainName)))=@EmployeeSubDomain THEN 0 ELSE 1 END;
 RETURN @SubDomainID;
END
GO

IF OBJECT_ID('dbo.ufn_BulletinIsManager') IS NULL EXEC('CREATE FUNCTION dbo.ufn_BulletinIsManager(@EmployeeID int,@SubDomainID int) RETURNS bit AS BEGIN RETURN 0 END');
GO
ALTER FUNCTION dbo.ufn_BulletinIsManager(@EmployeeID int,@SubDomainID int)
RETURNS bit AS
BEGIN
 RETURN CASE WHEN EXISTS(SELECT 1 FROM dbo.ProjectManager pm JOIN dbo.EmployeeInfo e ON e.ProjectManager=pm.ProjectManagerID WHERE LTRIM(RTRIM(CONVERT(varchar(50),pm.ProjectManagerName)))=CONVERT(varchar(20),@EmployeeID)AND dbo.ufn_BulletinEmployeeSubDomain(e.EmployeeID)=@SubDomainID AND ISNULL(e.IsDelete,0)=0)THEN 1 ELSE 0 END;
END
GO

ALTER FUNCTION dbo.ufn_BulletinFolderRights(@FolderID bigint,@EmployeeID int)
RETURNS TABLE AS RETURN
WITH P AS(SELECT FolderID,ParentFolderID,0 Lvl FROM dbo.BulletinFolderMaster WHERE FolderID=@FolderID UNION ALL SELECT f.FolderID,f.ParentFolderID,p.Lvl+1 FROM dbo.BulletinFolderMaster f JOIN P ON p.ParentFolderID=f.FolderID),
R AS(SELECT TOP(1)r.* FROM P JOIN dbo.BulletinFolderRights r ON r.FolderID=P.FolderID AND r.EmployeeID=@EmployeeID AND r.IsDeleted=0 JOIN dbo.BulletinFolderMaster target ON target.FolderID=@FolderID WHERE target.SubDomainID=dbo.ufn_BulletinEmployeeSubDomain(@EmployeeID) AND(P.Lvl=0 OR r.InheritToChildren=1)ORDER BY P.Lvl),
A AS(SELECT dbo.ufn_BulletinIsManager(@EmployeeID,target.SubDomainID)IsManager FROM dbo.BulletinFolderMaster target WHERE target.FolderID=@FolderID AND target.SubDomainID=dbo.ufn_BulletinEmployeeSubDomain(@EmployeeID))
SELECT CAST(CASE WHEN A.IsManager=1 THEN 1 ELSE ISNULL(R.CanView,0)END AS bit)CanView,CAST(CASE WHEN A.IsManager=1 THEN 1 ELSE ISNULL(R.CanUpload,0)END AS bit)CanUpload,CAST(CASE WHEN A.IsManager=1 THEN 1 ELSE ISNULL(R.CanCreateFolder,0)END AS bit)CanCreateFolder,CAST(CASE WHEN A.IsManager=1 THEN 1 ELSE ISNULL(R.CanRenameFolder,0)END AS bit)CanRenameFolder,CAST(CASE WHEN A.IsManager=1 THEN 1 ELSE ISNULL(R.CanMoveFolder,0)END AS bit)CanMoveFolder,CAST(CASE WHEN A.IsManager=1 THEN 1 ELSE ISNULL(R.CanDeleteFolder,0)END AS bit)CanDeleteFolder,CAST(CASE WHEN A.IsManager=1 THEN 1 ELSE ISNULL(R.CanManagePermissions,0)END AS bit)CanManagePermissions FROM A LEFT JOIN R ON 1=1 WHERE A.IsManager=1 OR R.FolderRightID IS NOT NULL;
GO

ALTER PROCEDURE dbo.usp_Bulletin_Bootstrap @EmployeeID int AS
BEGIN SET NOCOUNT ON;DECLARE @S int=dbo.ufn_BulletinEmployeeSubDomain(@EmployeeID);IF @S IS NULL THROW 51000,'EmployeeInfo.SubDomain does not match a configured subdomain.',1;
 SELECT TOP(1)e.EmployeeID,e.Department,e.Domain,e.WorkingBranch,@S SubDomainID,CAST(CASE WHEN dbo.ufn_BulletinIsManager(@EmployeeID,@S)=1 OR EXISTS(SELECT 1 FROM dbo.BulletinFolderRights r JOIN dbo.BulletinFolderMaster f ON f.FolderID=r.FolderID WHERE r.EmployeeID=@EmployeeID AND f.SubDomainID=@S AND r.CanManagePermissions=1 AND r.IsDeleted=0)THEN 1 ELSE 0 END AS bit)IsAdmin,dbo.ufn_BulletinIsManager(@EmployeeID,@S)IsManager FROM dbo.EmployeeInfo e WHERE e.EmployeeID=@EmployeeID;
 SELECT DISTINCT d.DomainID,d.DomainName FROM dbo.Domain d JOIN dbo.EmployeeInfo e ON e.Domain=d.DomainID WHERE dbo.ufn_BulletinEmployeeSubDomain(e.EmployeeID)=@S AND ISNULL(e.IsDelete,0)=0 ORDER BY d.DomainName;
 SELECT DISTINCT b.BranchID,b.BranchName FROM dbo.Branch b JOIN dbo.EmployeeInfo e ON e.WorkingBranch=b.BranchID WHERE dbo.ufn_BulletinEmployeeSubDomain(e.EmployeeID)=@S AND ISNULL(e.IsDelete,0)=0 ORDER BY b.BranchName;
 SELECT ProjectID,ProjectName FROM dbo.Project WHERE SubdomainID=@S AND ISNULL(IsDelete,0)=0 ORDER BY ProjectName;
 SELECT e.EmployeeID,e.Code+' - '+LTRIM(RTRIM(ISNULL(e.FirstName,'')+' '+ISNULL(e.lastName,'')))EmployeeName FROM dbo.EmployeeInfo e WHERE dbo.ufn_BulletinEmployeeSubDomain(e.EmployeeID)=@S AND ISNULL(e.IsDelete,0)=0 ORDER BY EmployeeName;
END
GO

ALTER PROCEDURE dbo.usp_Bulletin_TeamSetup @EmployeeID int AS
BEGIN SET NOCOUNT ON;DECLARE @S int=dbo.ufn_BulletinEmployeeSubDomain(@EmployeeID);IF @S IS NULL THROW 51000,'EmployeeInfo.SubDomain does not match a configured subdomain.',1;
 SELECT t.TeamID,t.TeamName,t.DomainID,t.SubDomainID,t.LocationID,t.ProjectID,d.DomainName,s.SubdomainName,ISNULL(b.BranchName,'All Locations')LocationName,ISNULL(p.ProjectName,'')ProjectName,(SELECT COUNT(*)FROM dbo.BulletinTeamMember m WHERE m.TeamID=t.TeamID AND m.IsDeleted=0)MemberCount FROM dbo.BulletinTeamMaster t JOIN dbo.Domain d ON d.DomainID=t.DomainID JOIN dbo.SubDomain s ON s.SubDomainID=t.SubDomainID LEFT JOIN dbo.Branch b ON b.BranchID=t.LocationID LEFT JOIN dbo.Project p ON p.ProjectID=t.ProjectID WHERE t.IsDeleted=0 AND t.SubDomainID=@S ORDER BY t.TeamName;
 SELECT DISTINCT d.DomainID,d.DomainName FROM dbo.Domain d JOIN dbo.EmployeeInfo e ON e.Domain=d.DomainID WHERE dbo.ufn_BulletinEmployeeSubDomain(e.EmployeeID)=@S AND ISNULL(e.IsDelete,0)=0 ORDER BY d.DomainName;
 SELECT SubDomainID,SubdomainName FROM dbo.SubDomain WHERE SubDomainID=@S;
 SELECT DISTINCT b.BranchID,b.BranchName FROM dbo.Branch b JOIN dbo.EmployeeInfo e ON e.WorkingBranch=b.BranchID WHERE dbo.ufn_BulletinEmployeeSubDomain(e.EmployeeID)=@S AND ISNULL(e.IsDelete,0)=0 ORDER BY b.BranchName;
 SELECT ProjectID,ProjectName FROM dbo.Project WHERE SubdomainID=@S AND ISNULL(IsDelete,0)=0 ORDER BY ProjectName;
 ;WITH F AS(SELECT f.FolderID,f.ParentFolderID,f.FolderName,0 FolderLevel,CAST(f.FolderName AS nvarchar(max))FolderPath FROM dbo.BulletinFolderMaster f WHERE f.SubDomainID=@S AND f.IsDeleted=0 AND f.IsSystem=0 AND(f.ParentFolderID IS NULL OR EXISTS(SELECT 1 FROM dbo.BulletinFolderMaster p WHERE p.FolderID=f.ParentFolderID AND p.IsSystem=1)) UNION ALL SELECT c.FolderID,c.ParentFolderID,c.FolderName,F.FolderLevel+1,CAST(F.FolderPath+N' / '+c.FolderName AS nvarchar(max))FROM dbo.BulletinFolderMaster c JOIN F ON c.ParentFolderID=F.FolderID WHERE c.SubDomainID=@S AND c.IsDeleted=0 AND c.IsSystem=0)SELECT F.* FROM F CROSS APPLY dbo.ufn_BulletinFolderRights(F.FolderID,@EmployeeID)r WHERE r.CanUpload=1 ORDER BY F.FolderPath OPTION(MAXRECURSION 100);
 SELECT m.TeamID,e.EmployeeID,e.Code+' : '+LTRIM(RTRIM(ISNULL(e.FirstName,'')+' '+ISNULL(e.lastName,'')))EmployeeName FROM dbo.BulletinTeamMember m JOIN dbo.BulletinTeamMaster t ON t.TeamID=m.TeamID JOIN dbo.EmployeeInfo e ON e.EmployeeID=m.EmployeeID WHERE t.SubDomainID=@S AND m.IsDeleted=0 ORDER BY e.Code;
END
GO

ALTER PROCEDURE dbo.usp_Bulletin_ProjectUsers @ProjectID int,@LocationID int=NULL,@EmployeeID int AS
BEGIN DECLARE @S int=dbo.ufn_BulletinEmployeeSubDomain(@EmployeeID);IF NOT EXISTS(SELECT 1 FROM dbo.Project WHERE ProjectID=@ProjectID AND SubdomainID=@S)THROW 51000,'Project is outside your subdomain.',1;SELECT DISTINCT e.EmployeeID,e.Code+' : '+LTRIM(RTRIM(ISNULL(e.FirstName,'')+' '+ISNULL(e.lastName,'')))EmployeeName FROM dbo.UserProjectConfiguration u JOIN dbo.EmployeeInfo e ON e.EmployeeID=u.UserID JOIN dbo.Project p ON p.ProjectID=u.ProjectID WHERE u.ProjectID=@ProjectID AND p.SubdomainID=@S AND dbo.ufn_BulletinEmployeeSubDomain(e.EmployeeID)=@S AND ISNULL(e.IsDelete,0)=0 AND(@LocationID IS NULL OR e.WorkingBranch=@LocationID)ORDER BY EmployeeName;END
GO

ALTER PROCEDURE dbo.usp_Bulletin_TeamSave @Action varchar(10)='Save',@TeamID int=0,@TeamName nvarchar(150)=NULL,@DomainID int=NULL,@SubDomainID int=NULL,@LocationID int=NULL,@ProjectID int=NULL,@MembersXml xml=NULL,@EmployeeID int AS
BEGIN SET XACT_ABORT ON;BEGIN TRAN;DECLARE @S int=dbo.ufn_BulletinEmployeeSubDomain(@EmployeeID);IF @S IS NULL OR(dbo.ufn_BulletinIsManager(@EmployeeID,@S)=0 AND NOT EXISTS(SELECT 1 FROM dbo.BulletinFolderRights r JOIN dbo.BulletinFolderMaster f ON f.FolderID=r.FolderID WHERE r.EmployeeID=@EmployeeID AND f.SubDomainID=@S AND r.CanManagePermissions=1 AND r.IsDeleted=0))THROW 51000,'Team management permission denied.',1;
 IF @Action='Delete'BEGIN UPDATE dbo.BulletinTeamMaster SET IsDeleted=1,ModifiedBy=@EmployeeID,ModifiedDate=SYSDATETIME()WHERE TeamID=@TeamID AND SubDomainID=@S;IF @@ROWCOUNT=0 THROW 51000,'Team access denied.',1;UPDATE dbo.BulletinTeamMember SET IsDeleted=1 WHERE TeamID=@TeamID;COMMIT;RETURN;END
 IF @SubDomainID<>@S OR @ProjectID IS NULL OR NOT EXISTS(SELECT 1 FROM dbo.Project WHERE ProjectID=@ProjectID AND SubdomainID=@S)THROW 51000,'Select a project in your subdomain.',1;
 IF @TeamID=0 BEGIN INSERT dbo.BulletinTeamMaster(TeamName,DomainID,SubDomainID,LocationID,ProjectID,CreatedBy)VALUES(@TeamName,@DomainID,@S,@LocationID,@ProjectID,@EmployeeID);SET @TeamID=SCOPE_IDENTITY();END ELSE BEGIN UPDATE dbo.BulletinTeamMaster SET TeamName=@TeamName,DomainID=@DomainID,LocationID=@LocationID,ProjectID=@ProjectID,ModifiedBy=@EmployeeID,ModifiedDate=SYSDATETIME()WHERE TeamID=@TeamID AND SubDomainID=@S AND IsDeleted=0;IF @@ROWCOUNT=0 THROW 51000,'Team access denied.',1;END
 UPDATE dbo.BulletinTeamMember SET IsDeleted=1 WHERE TeamID=@TeamID;MERGE dbo.BulletinTeamMember t USING(SELECT DISTINCT @TeamID TeamID,n.value('.','int')EmployeeID FROM @MembersXml.nodes('/members/id')x(n)JOIN dbo.UserProjectConfiguration u ON u.UserID=n.value('.','int')AND u.ProjectID=@ProjectID JOIN dbo.Project p ON p.ProjectID=u.ProjectID AND p.SubdomainID=@S JOIN dbo.EmployeeInfo e ON e.EmployeeID=u.UserID AND dbo.ufn_BulletinEmployeeSubDomain(e.EmployeeID)=@S AND ISNULL(e.IsDelete,0)=0 AND(@LocationID IS NULL OR e.WorkingBranch=@LocationID))s ON t.TeamID=s.TeamID AND t.EmployeeID=s.EmployeeID WHEN MATCHED THEN UPDATE SET IsDeleted=0 WHEN NOT MATCHED THEN INSERT(TeamID,EmployeeID,CreatedBy)VALUES(s.TeamID,s.EmployeeID,@EmployeeID);COMMIT;SELECT @TeamID TeamID;END
GO

ALTER PROCEDURE dbo.usp_Bulletin_TeamEmployees @TeamIDsXml xml,@EmployeeID int AS
BEGIN DECLARE @S int=dbo.ufn_BulletinEmployeeSubDomain(@EmployeeID);SELECT DISTINCT m.EmployeeID FROM @TeamIDsXml.nodes('/teams/id')x(n)JOIN dbo.BulletinTeamMaster t ON t.TeamID=x.n.value('.','int')AND t.SubDomainID=@S AND t.IsDeleted=0 JOIN dbo.BulletinTeamMember m ON m.TeamID=t.TeamID AND m.IsDeleted=0;END
GO

ALTER PROCEDURE dbo.usp_Bulletin_FolderSave @Action varchar(20),@FolderID bigint=NULL,@ParentFolderID bigint=NULL,@DestinationFolderID bigint=NULL,@FolderName nvarchar(150)=NULL,@EmployeeID int,@IPAddress varchar(50)=NULL AS
BEGIN SET XACT_ABORT ON;BEGIN TRAN;DECLARE @S int=dbo.ufn_BulletinEmployeeSubDomain(@EmployeeID),@Right bit=0;IF @Action='Create'AND @ParentFolderID IS NULL AND(dbo.ufn_BulletinIsManager(@EmployeeID,@S)=1 OR EXISTS(SELECT 1 FROM dbo.BulletinFolderRights r JOIN dbo.BulletinFolderMaster f ON f.FolderID=r.FolderID WHERE r.EmployeeID=@EmployeeID AND f.SubDomainID=@S AND r.CanManagePermissions=1 AND r.IsDeleted=0))SET @Right=1;ELSE SELECT @Right=CASE @Action WHEN'Create'THEN CanCreateFolder WHEN'Rename'THEN CanRenameFolder WHEN'Move'THEN CanMoveFolder WHEN'Delete'THEN CanDeleteFolder WHEN'Recover'THEN CanDeleteFolder ELSE 0 END FROM dbo.ufn_BulletinFolderRights(ISNULL(@FolderID,@ParentFolderID),@EmployeeID);IF @Right<>1 THROW 51000,'Folder permission denied.',1;
 IF @Action='Create'BEGIN IF @ParentFolderID IS NOT NULL AND NOT EXISTS(SELECT 1 FROM dbo.BulletinFolderMaster WHERE FolderID=@ParentFolderID AND SubDomainID=@S)THROW 51000,'Parent folder is outside your subdomain.',1;INSERT dbo.BulletinFolderMaster(ParentFolderID,FolderName,SubDomainID,CreatedBy)VALUES(@ParentFolderID,@FolderName,@S,@EmployeeID);SET @FolderID=SCOPE_IDENTITY();IF @ParentFolderID IS NULL INSERT dbo.BulletinFolderRights(FolderID,EmployeeID,CanView,CanUpload,CanCreateFolder,CanRenameFolder,CanMoveFolder,CanDeleteFolder,CanManagePermissions,InheritToChildren,GrantedBy)VALUES(@FolderID,@EmployeeID,1,1,1,1,1,1,1,1,@EmployeeID);END
 ELSE IF @Action='Rename'UPDATE dbo.BulletinFolderMaster SET FolderName=@FolderName,ModifiedBy=@EmployeeID,ModifiedDate=SYSDATETIME()WHERE FolderID=@FolderID AND SubDomainID=@S AND IsDeleted=0;
 ELSE IF @Action='Move'BEGIN IF NOT EXISTS(SELECT 1 FROM dbo.BulletinFolderMaster WHERE FolderID=@DestinationFolderID AND SubDomainID=@S)OR NOT EXISTS(SELECT 1 FROM dbo.ufn_BulletinFolderRights(@DestinationFolderID,@EmployeeID)WHERE CanCreateFolder=1)THROW 51000,'Destination permission denied.',1;DECLARE @Invalid bit=0;WITH X AS(SELECT FolderID,ParentFolderID FROM dbo.BulletinFolderMaster WHERE FolderID=@DestinationFolderID AND SubDomainID=@S UNION ALL SELECT f.FolderID,f.ParentFolderID FROM dbo.BulletinFolderMaster f JOIN X ON f.FolderID=X.ParentFolderID)SELECT @Invalid=1 FROM X WHERE FolderID=@FolderID;IF @FolderID=@DestinationFolderID OR @Invalid=1 THROW 51001,'Cannot move a folder into itself or its descendant.',1;UPDATE dbo.BulletinFolderMaster SET ParentFolderID=@DestinationFolderID,ModifiedBy=@EmployeeID,ModifiedDate=SYSDATETIME()WHERE FolderID=@FolderID AND SubDomainID=@S;END
 ELSE IF @Action IN('Delete','Recover')BEGIN;WITH X AS(SELECT FolderID FROM dbo.BulletinFolderMaster WHERE FolderID=@FolderID AND SubDomainID=@S UNION ALL SELECT f.FolderID FROM dbo.BulletinFolderMaster f JOIN X ON f.ParentFolderID=X.FolderID WHERE f.SubDomainID=@S)UPDATE f SET IsDeleted=CASE WHEN @Action='Delete'THEN 1 ELSE 0 END,ModifiedBy=@EmployeeID,ModifiedDate=SYSDATETIME()FROM dbo.BulletinFolderMaster f JOIN X ON X.FolderID=f.FolderID;WITH X AS(SELECT FolderID FROM dbo.BulletinFolderMaster WHERE FolderID=@FolderID AND SubDomainID=@S UNION ALL SELECT f.FolderID FROM dbo.BulletinFolderMaster f JOIN X ON f.ParentFolderID=X.FolderID WHERE f.SubDomainID=@S)UPDATE d SET IsDeleted=CASE WHEN @Action='Delete'THEN 1 ELSE 0 END FROM dbo.BulletinDocuments d JOIN X ON X.FolderID=d.FolderID;END COMMIT;SELECT @FolderID FolderID;END
GO

ALTER PROCEDURE dbo.usp_Bulletin_RightsSave @FolderID bigint,@TargetEmployeeID int,@CanView bit=NULL,@CanUpload bit=NULL,@CanCreateFolder bit=NULL,@CanRenameFolder bit=NULL,@CanMoveFolder bit=NULL,@CanDeleteFolder bit=NULL,@CanManagePermissions bit=NULL,@Inherit bit=1,@EmployeeID int AS
BEGIN DECLARE @S int=dbo.ufn_BulletinEmployeeSubDomain(@EmployeeID);IF NOT EXISTS(SELECT 1 FROM dbo.ufn_BulletinFolderRights(@FolderID,@EmployeeID)WHERE CanManagePermissions=1)OR ISNULL(dbo.ufn_BulletinEmployeeSubDomain(@TargetEmployeeID),-1)<>@S THROW 51000,'Permission management denied.',1;MERGE dbo.BulletinFolderRights t USING(SELECT @FolderID FolderID,@TargetEmployeeID EmployeeID)s ON t.FolderID=s.FolderID AND t.EmployeeID=s.EmployeeID WHEN MATCHED THEN UPDATE SET CanView=@CanView,CanUpload=@CanUpload,CanCreateFolder=@CanCreateFolder,CanRenameFolder=@CanRenameFolder,CanMoveFolder=@CanMoveFolder,CanDeleteFolder=@CanDeleteFolder,CanManagePermissions=@CanManagePermissions,InheritToChildren=@Inherit,IsDeleted=0,ModifiedBy=@EmployeeID,ModifiedDate=SYSDATETIME()WHEN NOT MATCHED THEN INSERT(FolderID,EmployeeID,CanView,CanUpload,CanCreateFolder,CanRenameFolder,CanMoveFolder,CanDeleteFolder,CanManagePermissions,InheritToChildren,GrantedBy)VALUES(@FolderID,@TargetEmployeeID,@CanView,@CanUpload,@CanCreateFolder,@CanRenameFolder,@CanMoveFolder,@CanDeleteFolder,@CanManagePermissions,@Inherit,@EmployeeID);END
GO

ALTER PROCEDURE dbo.usp_Bulletin_Save @BulletinID bigint=0,@FolderID bigint=NULL,@Title nvarchar(250),@Category nvarchar(80),@Priority varchar(20),@Summary nvarchar(2000),@ScheduleDate datetime2(0)=NULL,@RequireAcknowledgement bit,@AudienceXml xml,@EmployeeID int AS
BEGIN SET XACT_ABORT ON;BEGIN TRAN;DECLARE @S int=dbo.ufn_BulletinEmployeeSubDomain(@EmployeeID);IF @S IS NULL OR(dbo.ufn_BulletinIsManager(@EmployeeID,@S)=0 AND NOT EXISTS(SELECT 1 FROM dbo.BulletinFolderRights r JOIN dbo.BulletinFolderMaster f ON f.FolderID=r.FolderID WHERE r.EmployeeID=@EmployeeID AND f.SubDomainID=@S AND r.CanManagePermissions=1 AND r.IsDeleted=0))THROW 51000,'Manager permission required.',1;IF @FolderID IS NOT NULL AND NOT EXISTS(SELECT 1 FROM dbo.BulletinFolderMaster f CROSS APPLY dbo.ufn_BulletinFolderRights(f.FolderID,@EmployeeID)r WHERE f.FolderID=@FolderID AND f.SubDomainID=@S AND r.CanUpload=1)THROW 51000,'Folder is outside your subdomain or upload is denied.',1;
 IF @BulletinID=0 BEGIN INSERT dbo.BulletinMaster(FolderID,SubDomainID,Title,Category,Priority,Summary,PublishStatus,ScheduleDate,IsAcknowledgementRequired,CreatedBy)VALUES(@FolderID,@S,@Title,@Category,@Priority,@Summary,'Draft',@ScheduleDate,@RequireAcknowledgement,@EmployeeID);SET @BulletinID=SCOPE_IDENTITY();END ELSE BEGIN UPDATE dbo.BulletinMaster SET FolderID=@FolderID,Title=@Title,Category=@Category,Priority=@Priority,Summary=@Summary,ScheduleDate=@ScheduleDate,IsAcknowledgementRequired=@RequireAcknowledgement,ModifiedBy=@EmployeeID,ModifiedDate=SYSDATETIME()WHERE BulletinID=@BulletinID AND SubDomainID=@S AND CreatedBy=@EmployeeID AND IsDeleted=0 AND PublishStatus IN('Draft','Scheduled');IF @@ROWCOUNT=0 THROW 51000,'Bulletin access denied.',1;END
 DELETE dbo.BulletinAudience WHERE BulletinID=@BulletinID AND ResolvedEmployeeID IS NULL;DECLARE @Type varchar(20)=@AudienceXml.value('(/audience/@type)[1]','varchar(20)');IF @Type='AllOperations'INSERT dbo.BulletinAudience(BulletinID,AudienceType)VALUES(@BulletinID,@Type);ELSE INSERT dbo.BulletinAudience(BulletinID,AudienceType,DomainID,LocationID,ProjectID,EmployeeID)SELECT @BulletinID,@Type,CASE WHEN @Type='Domain'THEN CONVERT(int,N.value('.','varchar(20)'))END,CASE WHEN @Type='Location'THEN CONVERT(int,N.value('.','varchar(20)'))END,CASE WHEN @Type='Project'THEN CONVERT(int,N.value('.','varchar(20)'))END,CASE WHEN @Type='Employee'THEN CONVERT(int,N.value('.','varchar(20)'))END FROM @AudienceXml.nodes('/audience/value')X(N);COMMIT;SELECT @BulletinID BulletinID;END
GO

ALTER PROCEDURE dbo.usp_Bulletin_List @EmployeeID int,@From date=NULL,@To date=NULL,@DomainID int=NULL,@LocationID int=NULL,@ProjectID int=NULL,@Category nvarchar(80)=NULL,@Status varchar(20)=NULL AS
BEGIN SET NOCOUNT ON;DECLARE @S int=dbo.ufn_BulletinEmployeeSubDomain(@EmployeeID);SELECT b.BulletinID,b.Title,b.Category,b.Priority,b.Summary,b.PublishDate,b.ScheduleDate,b.PublishStatus,b.IsAcknowledgementRequired,COALESCE(NULLIF(ec.PsuedoName,''),e.Code)PublishedBy,ISNULL(t.Status,b.PublishStatus)Status,t.ReadDateTime,t.AcknowledgedDateTime,d.DocumentID,d.CurrentVersionID,d.DisplayName Attachment,CAST(CASE WHEN b.CreatedBy=@EmployeeID THEN 1 ELSE 0 END AS bit)CanEdit,CAST(CASE WHEN t.TrackingID IS NULL THEN 0 ELSE 1 END AS bit)IsTargeted FROM dbo.BulletinMaster b LEFT JOIN dbo.BulletinUserTracking t ON t.BulletinID=b.BulletinID AND t.EmployeeID=@EmployeeID LEFT JOIN dbo.EmployeeInfo e ON e.EmployeeID=b.PublishedBy OUTER APPLY(SELECT TOP(1)c.PsuedoName FROM dbo.EmployeeConfiguration c WHERE c.EmployeeID=b.PublishedBy AND ISNULL(c.IsDelete,0)=0 ORDER BY c.EmpConfigrationID DESC)ec LEFT JOIN dbo.BulletinDocuments d ON d.BulletinID=b.BulletinID AND d.IsDeleted=0 WHERE b.SubDomainID=@S AND b.IsDeleted=0 AND(t.TrackingID IS NOT NULL OR b.CreatedBy=@EmployeeID)AND(@From IS NULL OR CAST(ISNULL(b.PublishDate,b.CreatedDate)AS date)>=@From)AND(@To IS NULL OR CAST(ISNULL(b.PublishDate,b.CreatedDate)AS date)<=@To)AND(@Category IS NULL OR b.Category=@Category)AND(@Status IS NULL OR(@Status='Important'AND b.Priority IN('Important','Critical'))OR(@Status='Archived'AND b.PublishStatus='Archived')OR(@Status NOT IN('Important','Archived')AND ISNULL(t.Status,b.PublishStatus)=@Status))AND EXISTS(SELECT 1 FROM dbo.EmployeeInfo me WHERE me.EmployeeID=@EmployeeID AND dbo.ufn_BulletinEmployeeSubDomain(me.EmployeeID)=@S AND(@DomainID IS NULL OR me.Domain=@DomainID)AND(@LocationID IS NULL OR me.WorkingBranch=@LocationID)AND(@ProjectID IS NULL OR EXISTS(SELECT 1 FROM dbo.UserProjectConfiguration u JOIN dbo.Project fp ON fp.ProjectID=u.ProjectID WHERE u.UserID=@EmployeeID AND u.ProjectID=@ProjectID AND fp.SubdomainID=@S)))ORDER BY CASE b.Priority WHEN'Critical'THEN 1 WHEN'Important'THEN 2 ELSE 3 END,ISNULL(b.PublishDate,b.CreatedDate)DESC;END
GO

ALTER PROCEDURE dbo.usp_Bulletin_Track @BulletinID bigint,@EmployeeID int,@Action varchar(20),@DocumentVersionID bigint=NULL AS
BEGIN SET XACT_ABORT ON;BEGIN TRAN;DECLARE @S int=dbo.ufn_BulletinEmployeeSubDomain(@EmployeeID);IF NOT EXISTS(SELECT 1 FROM dbo.BulletinMaster b WHERE b.BulletinID=@BulletinID AND b.SubDomainID=@S AND b.IsDeleted=0 AND(EXISTS(SELECT 1 FROM dbo.BulletinUserTracking t WHERE t.BulletinID=b.BulletinID AND t.EmployeeID=@EmployeeID)OR b.CreatedBy=@EmployeeID))THROW 51000,'Bulletin access denied.',1;UPDATE dbo.BulletinUserTracking SET FirstViewedDateTime=CASE WHEN @Action='View'AND FirstViewedDateTime IS NULL THEN SYSDATETIME()ELSE FirstViewedDateTime END,LastViewedDateTime=CASE WHEN @Action='View'THEN SYSDATETIME()ELSE LastViewedDateTime END,ReadDateTime=CASE WHEN @Action='Read'THEN ISNULL(ReadDateTime,SYSDATETIME())ELSE ReadDateTime END,AcknowledgedDateTime=CASE WHEN @Action='Acknowledge'THEN ISNULL(AcknowledgedDateTime,SYSDATETIME())ELSE AcknowledgedDateTime END,DocumentVersionID=ISNULL(@DocumentVersionID,DocumentVersionID),Status=CASE WHEN @Action='Acknowledge'THEN'Acknowledged'WHEN @Action='Read'AND Status<>'Acknowledged'THEN'Read'WHEN @Action='View'AND Status='Unread'THEN'Viewed'ELSE Status END WHERE BulletinID=@BulletinID AND EmployeeID=@EmployeeID;COMMIT;END
GO

ALTER PROCEDURE dbo.usp_Bulletin_Publish @BulletinID bigint,@Action varchar(20),@EmployeeID int AS
BEGIN SET XACT_ABORT ON;BEGIN TRAN;DECLARE @S int=dbo.ufn_BulletinEmployeeSubDomain(@EmployeeID);IF NOT EXISTS(SELECT 1 FROM dbo.BulletinMaster WHERE BulletinID=@BulletinID AND SubDomainID=@S AND CreatedBy=@EmployeeID AND IsDeleted=0)THROW 51000,'Bulletin access denied.',1;IF @Action='Archive'BEGIN UPDATE dbo.BulletinMaster SET PublishStatus='Archived',IsArchived=1,ModifiedBy=@EmployeeID,ModifiedDate=SYSDATETIME()WHERE BulletinID=@BulletinID AND SubDomainID=@S;COMMIT;RETURN;END
 DECLARE @PublishDate datetime2(0)=CASE WHEN @Action='Schedule'THEN(SELECT ScheduleDate FROM dbo.BulletinMaster WHERE BulletinID=@BulletinID)ELSE SYSDATETIME()END,@Folder bigint=(SELECT FolderID FROM dbo.BulletinMaster WHERE BulletinID=@BulletinID),@Root bigint,@Month bigint,@MonthName varchar(30);IF @Folder IS NULL BEGIN SELECT TOP(1)@Root=FolderID FROM dbo.BulletinFolderMaster f CROSS APPLY dbo.ufn_BulletinFolderRights(f.FolderID,@EmployeeID)r WHERE f.ParentFolderID IS NULL AND f.SubDomainID=@S AND f.IsDeleted=0 AND r.CanUpload=1 ORDER BY f.FolderID;IF @Root IS NULL THROW 51000,'Create an authorized root folder for this subdomain before publishing.',1;SET @MonthName=DATENAME(month,@PublishDate)+'-'+CONVERT(varchar(4),YEAR(@PublishDate));SELECT @Month=FolderID FROM dbo.BulletinFolderMaster WHERE ParentFolderID=@Root AND SubDomainID=@S AND FolderName=@MonthName AND IsDeleted=0;IF @Month IS NULL BEGIN INSERT dbo.BulletinFolderMaster(ParentFolderID,FolderName,SubDomainID,IsSystem,CreatedBy)VALUES(@Root,@MonthName,@S,1,@EmployeeID);SET @Month=SCOPE_IDENTITY();END;SET @Folder=@Month;END
 UPDATE dbo.BulletinMaster SET FolderID=@Folder,PublishStatus=CASE WHEN @Action='Schedule'THEN'Scheduled'ELSE'Published'END,PublishDate=@PublishDate,PublishedBy=@EmployeeID WHERE BulletinID=@BulletinID AND SubDomainID=@S;DELETE dbo.BulletinAudience WHERE BulletinID=@BulletinID AND ResolvedEmployeeID IS NOT NULL;
 ;WITH T AS(SELECT DISTINCT e.EmployeeID FROM dbo.BulletinAudience a CROSS JOIN dbo.EmployeeInfo e WHERE a.BulletinID=@BulletinID AND a.ResolvedEmployeeID IS NULL AND dbo.ufn_BulletinEmployeeSubDomain(e.EmployeeID)=@S AND ISNULL(e.IsDelete,0)=0 AND((a.AudienceType='AllOperations')OR(a.AudienceType='Domain'AND e.Domain=a.DomainID)OR(a.AudienceType='Location'AND e.WorkingBranch=a.LocationID)OR(a.AudienceType='Project'AND EXISTS(SELECT 1 FROM dbo.UserProjectConfiguration u WHERE u.UserID=e.EmployeeID AND u.ProjectID=a.ProjectID))OR(a.AudienceType='Employee'AND e.EmployeeID=a.EmployeeID)))INSERT dbo.BulletinAudience(BulletinID,AudienceType,ResolvedEmployeeID,ResolvedDate)SELECT @BulletinID,'Employee',EmployeeID,SYSDATETIME()FROM T;MERGE dbo.BulletinUserTracking t USING(SELECT DISTINCT @BulletinID BulletinID,ResolvedEmployeeID EmployeeID FROM dbo.BulletinAudience WHERE BulletinID=@BulletinID AND ResolvedEmployeeID IS NOT NULL)s ON t.BulletinID=s.BulletinID AND t.EmployeeID=s.EmployeeID WHEN NOT MATCHED THEN INSERT(BulletinID,EmployeeID,Status)VALUES(s.BulletinID,s.EmployeeID,'Unread');COMMIT;END
GO

ALTER PROCEDURE dbo.usp_Bulletin_DiscardDraft @BulletinID bigint,@EmployeeID int AS BEGIN SET XACT_ABORT ON;BEGIN TRAN;DECLARE @S int=dbo.ufn_BulletinEmployeeSubDomain(@EmployeeID);IF NOT EXISTS(SELECT 1 FROM dbo.BulletinMaster WHERE BulletinID=@BulletinID AND SubDomainID=@S AND CreatedBy=@EmployeeID AND PublishStatus IN('Draft','Scheduled'))THROW 51000,'Draft cannot be removed.',1;UPDATE dbo.BulletinMaster SET IsDeleted=1,ModifiedBy=@EmployeeID,ModifiedDate=SYSDATETIME()WHERE BulletinID=@BulletinID AND SubDomainID=@S;UPDATE dbo.BulletinDocuments SET IsDeleted=1 WHERE BulletinID=@BulletinID;COMMIT;END
GO

ALTER PROCEDURE dbo.usp_Bulletin_DocumentSave @FolderID bigint,@BulletinID bigint=NULL,@DocumentID bigint=NULL,@OriginalFileName nvarchar(255),@StoredFileName varchar(80),@PdfStoredFileName varchar(80)=NULL,@ContentType varchar(150),@FileSize bigint,@Sha256 varchar(64),@EmployeeID int AS
BEGIN SET XACT_ABORT ON;BEGIN TRAN;DECLARE @S int=dbo.ufn_BulletinEmployeeSubDomain(@EmployeeID);IF NOT EXISTS(SELECT 1 FROM dbo.BulletinFolderMaster f CROSS APPLY dbo.ufn_BulletinFolderRights(f.FolderID,@EmployeeID)r WHERE f.FolderID=@FolderID AND f.SubDomainID=@S AND r.CanUpload=1)OR(@BulletinID IS NOT NULL AND NOT EXISTS(SELECT 1 FROM dbo.BulletinMaster WHERE BulletinID=@BulletinID AND SubDomainID=@S AND CreatedBy=@EmployeeID AND IsDeleted=0))THROW 51000,'Upload permission denied.',1;IF @DocumentID IS NULL BEGIN DECLARE @Now datetime2(0)=DATEADD(minute,330,SYSUTCDATETIME()),@Month bigint,@Name varchar(30);SET @Name=DATENAME(month,@Now)+'-'+CONVERT(varchar(4),YEAR(@Now));SELECT @Month=FolderID FROM dbo.BulletinFolderMaster WITH(UPDLOCK,HOLDLOCK)WHERE ParentFolderID=@FolderID AND SubDomainID=@S AND FolderName=@Name AND IsDeleted=0;IF @Month IS NULL BEGIN INSERT dbo.BulletinFolderMaster(ParentFolderID,FolderName,SubDomainID,IsSystem,CreatedBy)VALUES(@FolderID,@Name,@S,1,@EmployeeID);SET @Month=SCOPE_IDENTITY();END;SET @FolderID=@Month;INSERT dbo.BulletinDocuments(BulletinID,FolderID,DisplayName,CreatedBy)VALUES(@BulletinID,@FolderID,@OriginalFileName,@EmployeeID);SET @DocumentID=SCOPE_IDENTITY();END ELSE IF NOT EXISTS(SELECT 1 FROM dbo.BulletinDocuments d JOIN dbo.BulletinFolderMaster f ON f.FolderID=d.FolderID WHERE d.DocumentID=@DocumentID AND d.FolderID=@FolderID AND f.SubDomainID=@S AND d.IsDeleted=0)THROW 51001,'Document not found.',1;DECLARE @Version int=ISNULL((SELECT MAX(VersionNo)FROM dbo.BulletinDocumentVersions WITH(UPDLOCK,HOLDLOCK)WHERE DocumentID=@DocumentID),0)+1,@VersionID bigint;INSERT dbo.BulletinDocumentVersions(DocumentID,VersionNo,OriginalFileName,StoredFileName,PdfStoredFileName,ContentType,FileSize,Sha256,UploadedBy)VALUES(@DocumentID,@Version,@OriginalFileName,@StoredFileName,@PdfStoredFileName,@ContentType,@FileSize,@Sha256,@EmployeeID);SET @VersionID=SCOPE_IDENTITY();UPDATE dbo.BulletinDocuments SET CurrentVersionID=@VersionID,DisplayName=@OriginalFileName WHERE DocumentID=@DocumentID;COMMIT;SELECT @VersionID DocumentVersionID;END
GO

ALTER PROCEDURE dbo.usp_Bulletin_Report @EmployeeID int,@From date=NULL,@To date=NULL,@DomainID int=NULL,@LocationID int=NULL,@ProjectID int=NULL,@TargetEmployeeID int=NULL AS
BEGIN SET NOCOUNT ON;DECLARE @S int=dbo.ufn_BulletinEmployeeSubDomain(@EmployeeID);IF dbo.ufn_BulletinIsManager(@EmployeeID,@S)=0 AND NOT EXISTS(SELECT 1 FROM dbo.BulletinFolderRights r JOIN dbo.BulletinFolderMaster f ON f.FolderID=r.FolderID WHERE r.EmployeeID=@EmployeeID AND f.SubDomainID=@S AND r.CanManagePermissions=1 AND r.IsDeleted=0)THROW 51000,'Report access denied.',1;
 SELECT b.BulletinID,b.Title,b.PublishDate,COUNT(*)TargetedCount,SUM(CASE WHEN t.Status='Unread'THEN 1 ELSE 0 END)UnreadCount,SUM(CASE WHEN t.Status='Viewed'THEN 1 ELSE 0 END)ViewedCount,SUM(CASE WHEN t.Status IN('Read','Acknowledged')THEN 1 ELSE 0 END)ReadCount,SUM(CASE WHEN t.Status='Acknowledged'THEN 1 ELSE 0 END)AcknowledgedCount FROM dbo.BulletinUserTracking t JOIN dbo.BulletinMaster b ON b.BulletinID=t.BulletinID JOIN dbo.EmployeeInfo e ON e.EmployeeID=t.EmployeeID WHERE b.SubDomainID=@S AND dbo.ufn_BulletinEmployeeSubDomain(e.EmployeeID)=@S AND b.IsDeleted=0 AND(@From IS NULL OR CAST(b.PublishDate AS date)>=@From)AND(@To IS NULL OR CAST(b.PublishDate AS date)<=@To)AND(@DomainID IS NULL OR e.Domain=@DomainID)AND(@LocationID IS NULL OR e.WorkingBranch=@LocationID)AND(@ProjectID IS NULL OR EXISTS(SELECT 1 FROM dbo.UserProjectConfiguration u WHERE u.UserID=e.EmployeeID AND u.ProjectID=@ProjectID))AND(@TargetEmployeeID IS NULL OR e.EmployeeID=@TargetEmployeeID)GROUP BY b.BulletinID,b.Title,b.PublishDate ORDER BY b.PublishDate DESC,b.Title;
 SELECT t.BulletinID,e.EmployeeID,e.Code,LTRIM(RTRIM(ISNULL(e.FirstName,'')+' '+ISNULL(e.lastName,'')))EmployeeName,d.DomainName,br.BranchName,ep.ProjectName,t.Status,t.FirstViewedDateTime,t.LastViewedDateTime,t.ReadDateTime,t.AcknowledgedDateTime FROM dbo.BulletinUserTracking t JOIN dbo.BulletinMaster b ON b.BulletinID=t.BulletinID JOIN dbo.EmployeeInfo e ON e.EmployeeID=t.EmployeeID OUTER APPLY(SELECT TOP(1)p.ProjectName FROM dbo.UserProjectConfiguration u JOIN dbo.Project p ON p.ProjectID=u.ProjectID WHERE u.UserID=e.EmployeeID AND p.SubdomainID=@S ORDER BY CASE WHEN p.ProjectID=@ProjectID THEN 0 ELSE 1 END,p.ProjectName)ep LEFT JOIN dbo.Domain d ON d.DomainID=e.Domain LEFT JOIN dbo.Branch br ON br.BranchID=e.WorkingBranch WHERE b.SubDomainID=@S AND dbo.ufn_BulletinEmployeeSubDomain(e.EmployeeID)=@S AND b.IsDeleted=0 AND(@From IS NULL OR CAST(b.PublishDate AS date)>=@From)AND(@To IS NULL OR CAST(b.PublishDate AS date)<=@To)AND(@DomainID IS NULL OR e.Domain=@DomainID)AND(@LocationID IS NULL OR e.WorkingBranch=@LocationID)AND(@ProjectID IS NULL OR EXISTS(SELECT 1 FROM dbo.UserProjectConfiguration u WHERE u.UserID=e.EmployeeID AND u.ProjectID=@ProjectID))AND(@TargetEmployeeID IS NULL OR e.EmployeeID=@TargetEmployeeID)ORDER BY t.BulletinID,e.Code;
END
GO
